mapper.select:
SELECT batch_no, business_date, channel_code, bill_source, status, channel_count,
       internal_count, matched_count, difference_count
FROM t_reconciliation_batch WHERE batch_no = #{batchNo}

SELECT difference_no, batch_no, difference_type, payment_order_id, channel_amount, internal_amount,
       status, resolution, remark, detected_at, resolved_at
FROM t_reconciliation_difference

    AND batch_no = #{batchNo}
    AND difference_type = #{differenceType}
    AND status = #{status}

ORDER BY detected_at DESC
LIMIT #{pageSize} OFFSET ${(pageNo - 1) * pageSize}

SELECT COUNT(1) FROM t_reconciliation_difference

    AND batch_no = #{batchNo}
    AND difference_type = #{differenceType}
    AND status = #{status}
